import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

@WebServlet("/api/reports")
public class ReportGeneratorServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportGeneratorServlet.class.getName());

    // Template engine for report generation
    private String renderTemplate(String template, Map<String, String> params) {
        StringSubstitutor sub = new StringSubstitutor(params);
        return sub.replace(template);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");

        if (reportId == null || !reportId.matches("[a-zA-Z0-9_-]+")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        try {
            Connection conn = getConnection();
            String query = buildQuery(reportId, req);
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            StringBuilder output = new StringBuilder();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                Map<String, String> row = new HashMap<>();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnName(i), rs.getString(i));
                }
                output.append(renderTemplate(getTemplate(reportId), row));
            }

            resp.setContentType("text/html");
            resp.getWriter().write(output.toString());

            rs.close();
            stmt.close();
            conn.close();
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String reportId, HttpServletRequest req) {
        String baseTable = "reports_" + reportId;
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        StringBuilder sql = new StringBuilder();
        sql.append("SELECT * FROM ").append(baseTable);

        boolean hasWhere = false;
        if (dateFrom != null) {
            sql.append(" WHERE created_at >= '").append(dateFrom).append("'");
            hasWhere = true;
        }
        if (dateTo != null) {
            sql.append(hasWhere ? " AND " : " WHERE ");
            sql.append("created_at <= '").append(dateTo).append("'");
            hasWhere = true;
        }
        if (filterExpr != null) {
            sql.append(hasWhere ? " AND " : " WHERE ");
            sql.append(filterExpr);
        }
        if (sortCol != null) {
            sql.append(" ORDER BY ").append(sortCol);
        }

        return sql.toString();
    }

    private String getTemplate(String reportId) {
        // Templates stored in config; simplified here
        return "<tr><td>${name}</td><td>${value}</td><td>${status}</td></tr>";
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }
}
